def remove_at(a, i):
    out = list(a)
    for k in range(i, len(a) - 1):
        out[k] = out[k + 1]
    out[-1] = None
    return out

def copies(n, grow=None):
    cap, size, total = 1, 0, 0
    for _ in range(n):
        if size == cap:
            total += size
            cap = cap * 2 if grow is None else cap + grow
        size += 1
    return total

def reverse(head):
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next
    return prev

def balanced(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def two_sum(nums, target):
    seen = {}
    for j, x in enumerate(nums):
        if target - x in seen:
            return (seen[target - x], j)
        seen[x] = j

def flatten(x):
    out = []
    for item in x:
        if isinstance(item, list):
            out += flatten(item)
        else:
            out.append(item)
    return out

def merge(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    return out + a[i:] + b[j:]

def partition(a):
    a = list(a)
    pivot = a[-1]
    i = -1
    for j in range(len(a) - 1):
        if a[j] <= pivot:
            i += 1
            a[i], a[j] = a[j], a[i]
    a[i + 1], a[-1] = a[-1], a[i + 1]
    return a, i + 1

def bst_height(values):
    root = None
    def insert(node, k):
        if node is None:
            return [k, None, None]
        if k < node[0]:
            node[1] = insert(node[1], k)
        else:
            node[2] = insert(node[2], k)
        return node
    def height(node):
        return 0 if node is None else 1 + max(height(node[1]), height(node[2]))
    for v in values:
        root = insert(root, v)
    return height(root)

from collections import deque
def shortest_hops(graph, start, goal):
    dist = {start: 0}
    q = deque([start])
    while q:
        u = q.popleft()
        for v in graph[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist.get(goal, -1)

import heapq
def dijkstra(graph, source):
    dist = {source: 0}
    pq = [(0, source)]
    done = set()
    while pq:
        d, u = heapq.heappop(pq)
        if u in done:
            continue
        done.add(u)
        for v, w in graph[u].items():
            if v not in dist or d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))
    return dist

def min_coins(coins, amount):
    INF = float('inf')
    best = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and best[a - c] + 1 < best[a]:
                best[a] = best[a - c] + 1
    return -1 if best[amount] == INF else best[amount]
